(async()=>{
const studio=(await import('/src/studio/store.ts')).useStudio,id=studio.getState().job.id;
const history=await import('/src/studio/assistant/chatHistory.ts');
const thread={id:'audit-saved-chat',updatedAt:new Date().toISOString(),entries:[{id:'audit-user',kind:'user',text:'Keep my Willow conversation'},{id:'audit-reply',kind:'assistant',text:'The Willow design belongs to this project.'}],contents:[{role:'user',parts:[{text:'Keep my Willow conversation'}]},{role:'model',parts:[{text:'The Willow design belongs to this project.'}]}],busy:false,error:null};
await history.saveChatArchive({projectId:id,revision:0,activeId:thread.id,threads:[thread]},0);
const persistence=await import('/src/studio/architect/persistence.ts'), bridge=await import('/src/studio/assistant/architectBridge.ts');
const session=persistence.loadArchitect(id,localStorage);
const p=bridge.prepareArchitectElements(session.value,{expectedJobId:id,expectedRevision:session.value.revision,operations:[{kind:'footprint',levelId:session.value.levels[0].id,points:[[0,0],[6000,0],[6000,4000],[0,4000]],name:'Willow project model'}]}).draft;
const saved=persistence.saveArchitect(session,p,localStorage);if(saved.error)throw Error(saved.error);
studio.getState().setModelSelection('designed');
const hash=studio.getState().designedBuilding.source.sha256;
const sw=(await import('/src/studio/assistant/projectSwitch.ts')).switchProject;
const saveJob=(await import('/src/studio/persistence.ts')).saveFencingJob;
const deps={store:studio,storage:localStorage,saveJob:(job,options)=>saveJob(job,undefined,options),busy:false};
let result=await sw(null,deps);if(!result.ok)throw Error(result.error+' '+JSON.stringify({stage:result.stage,hydrated:studio.getState().persistenceHydrated,status:studio.getState().hydrationStatus,blocked:studio.getState().persistenceRecoveryBlocked,error:studio.getState().persistenceError}));
const other=studio.getState().job.id;
if(other===id||studio.getState().designedBuilding!==null||studio.getState().modelSelection!==null)throw Error('New project inherited prior model');
result=await sw(id,deps);if(!result.ok)throw Error(result.error+' '+JSON.stringify({stage:result.stage,hydrated:studio.getState().persistenceHydrated,status:studio.getState().hydrationStatus,blocked:studio.getState().persistenceRecoveryBlocked,error:studio.getState().persistenceError}));
if(studio.getState().designedBuilding?.source.sha256!==hash||studio.getState().modelSelection!=='designed')throw Error('Original model not restored');
return {original:id,other,hash,switchIsolation:true};
})()
